DO $native$ DECLARE name text; definition text; predicate text; BEGIN
 FOREACH name IN ARRAY ARRAY['run_producers_execution_profile_id_check','run_producers_execution_profile_digest_check','run_producers_full03_exact_check'] LOOP
  SELECT pg_get_constraintdef(oid) INTO STRICT definition FROM pg_constraint WHERE conrelid='research.run_producers'::regclass AND conname=name;
  IF left(definition,7)<>'CHECK (' OR right(definition,1)<>')' THEN RAISE EXCEPTION 'unsupported exact recipe constraint'; END IF;
  EXECUTE format('ALTER TABLE research.run_producers DROP CONSTRAINT %I',name);
  EXECUTE format('ALTER TABLE research.run_producers ADD CONSTRAINT %I CHECK ((%s) OR (%s))',name,substring(definition from 8 for char_length(definition)-8),'execution_profile_id=''p10.delta-event-driven-limit-oco-search-1h.v1'' AND execution_profile_digest=''2b69015b8975e3097cc797999188a6d6b75e29ce52fc3ad2d4c35026ab7f0d73'' AND execution_adapter_id=''full03.delta-rsi.v1'' AND adapter_contract_digest=''eb357785783f1fc919a926a5d53c19c514422a9a87c6dc45d3425e42da21d202'' AND alpha_id=''delta-rsi-polynomial-alpha'' AND alpha_version_id=''av_delta_rsi_polynomial_alpha_1_0_13''');
 END LOOP;
 SELECT pg_get_expr(indpred,indrelid) INTO STRICT predicate FROM pg_index WHERE indexrelid='research.alpha_versions_legacy_code_entrypoint_unique'::regclass;
 IF predicate IS NULL THEN RAISE EXCEPTION 'legacy identity must retain a partial predicate'; END IF;
 DROP INDEX research.alpha_versions_legacy_code_entrypoint_unique;
 EXECUTE format('CREATE UNIQUE INDEX alpha_versions_legacy_code_entrypoint_unique ON research.alpha_versions(workspace_id,alpha_id,code_digest,entrypoint) WHERE (%s) AND alpha_version_id <> %L',predicate,'av_delta_rsi_polynomial_alpha_1_0_13');
 SELECT pg_get_constraintdef(oid) INTO STRICT definition FROM pg_constraint WHERE conrelid='research.execution_adapter_bindings'::regclass AND conname='execution_adapter_bindings_full03_exact_check';
 ALTER TABLE research.execution_adapter_bindings DROP CONSTRAINT execution_adapter_bindings_full03_exact_check;
 EXECUTE format('ALTER TABLE research.execution_adapter_bindings ADD CONSTRAINT execution_adapter_bindings_full03_exact_check CHECK ((%s) OR (adapter_id=%L AND alpha_version_id=%L AND contract_digest=%L))',substring(definition from 8 for char_length(definition)-8),'full03.delta-rsi.v1','av_delta_rsi_polynomial_alpha_1_0_13','eb357785783f1fc919a926a5d53c19c514422a9a87c6dc45d3425e42da21d202');
END $native$;
